# rubik.s - Stage 4: optimal 2x2x2 solver (IDA*) in RV32I for Ripes.
#
# Build for the CLI:  cat ida/rubik.s ida/tables.s > /tmp/build.s
# (tables.s is generated by ida/pdb.c and holds perm_R.., ori_R..,
#  perm_pdb, ori_pdb, perm_row, ori_row)
#
# Exit codes: 0 = solved and verified, 1 = path check failed, 2 = invalid input

.data
# Search stack: 12 frames (depth 0..11) of 20 bytes.  First in .data so it
# starts word-aligned; 20 is a multiple of 4, so every frame stays aligned.
#   0 p (.half)   2 o (.half)   4 cp (.half)   6 co (.half)
#   8 pp (.word) 12 op (.word) 16 face  17 turn  18 mface  19 mturn (.byte)
stack:  .zero 240
fact:   .half 720, 120, 24, 6, 2, 1, 1     # (6 - i)!: Lehmer code weights
names:  .string "RBD"                      # face letters for printing
state:  .string "21345671111111"           # input: 7 cubie digits, 7 orientation digits
        .align 2                           # tables.s continues .data with .half tables

.text
main:
    # ---------------------------------------------------------------
    # 1. Parse the input.  Result: s0 = p (0..5039), s1 = o (0..728).
    #    Any problem jumps to `invalid`.
    # ---------------------------------------------------------------

    # a0 = address of state

    # (1) Length: bytes 0..13 are non-zero, byte 14 is zero.
    la   t0, state          # pointer
    mv   t1, t0             # keep the start

len_loop:
    lbu  t2, 0(t0)          # current character
    beqz t2, len_done       # '\0' => done
    addi t0, t0, 1          # ptr++
    j    len_loop

len_done:
    sub  t3, t0, t1         # length = ptr - start
    li   t4, 14             # expected length
    bne  t3, t4, invalid    # length != 14

    # (2) Permutation digits, i = 0..6:
    #       c = state[i] - '1'
    #       c must be 0..6         (one unsigned compare catches c < 0 too)
    #       bit c of a "seen" mask must be clear, then set it
    #     No final seen == 0x7F check: 7 digits, each 0..6, none repeated,
    #     must be 0..6 exactly once (pigeonhole).
    la   t0, state          # pointer
    li   t4, 0              # seen = 0
    li   t5, 7              # counter
    li   t6, 7              # upper bound

perm_loop:
    lbu  t2, 0(t0)          # character
    addi t2, t2, -49        # c = character - '1'
    bgeu t2, t6, invalid    # c >= 7 (unsigned) => invalid

    li   t3, 1              # bit = 1
    sll  t3, t3, t2         # bit = 1 << c

    and  t1, t4, t3         # tmp = seen & bit
    bnez t1, invalid        # seen before

    or   t4, t4, t3         # seen |= bit

    addi t0, t0, 1          # ptr++
    addi t5, t5, -1         # counter--
    bnez t5, perm_loop

    # (3) Orientation digits, i = 0..6:
    #       d = state[7 + i] - '1'
    #       d must be 0..2
    #       sum += d
    #       for i < 6 only: o = o * 3 + d      (no multiply: shift + add)
    #     sum mod 3 must be 0      (sum <= 14: subtract 3 while sum >= 3)
    #     One loop of 7 with a skip for the 7th o update: parse runs once,
    #     so code size wins over the extra branch per iteration.
    #     t0 already points at state[7]

    li   s1, 0              # o = 0
    li   t1, 0              # sum_mod3 = 0
    li   t5, 7              # counter = 7
    li   t6, 3              # range limit and mod-3 constant

ori_loop:
    lbu  t2, 0(t0)          # read digit
    addi t2, t2, -49        # d = digit - '1'
    bgeu t2, t6, invalid    # d >= 3 => invalid

    # sum_mod3 = (sum_mod3 + d) mod 3
    add  t1, t1, t2         # sum_mod3 += d
    addi t3, t1, -3         # tmp = sum_mod3 - 3
    bltz t3, ori_skip       # if tmp < 0, keep old value
    mv   t1, t3             # sum_mod3 = tmp

ori_skip:

    # skip o update for the 7th digit
    li   t4, 1
    beq  t5, t4, ori_next

    slli t3, s1, 1          # tmp = o << 1
    add  s1, s1, t3         # o = o * 3
    add  s1, s1, t2         # o = o * 3 + d

ori_next:
    addi t0, t0, 1          # ptr++
    addi t5, t5, -1         # counter--
    bnez t5, ori_loop

    bnez t1, invalid        # sum_mod3 must be 0

    # (4) Lehmer code, i = 0..6:
    #       w = fact[i]
    #       for j = i + 1..6: if state[j] < state[i], p += w
    #     (comparing the ASCII digits directly keeps their order)
    #     The outer loop stops at i = 5: for i = 6 there is no j.
    li   s0, 0              # p = 0
    la   t0, state          # i pointer
    la   t5, fact           # weight pointer
    la   t6, state+7        # end
    addi t4, t6, -1         # outer_end = &state[6]

lehmer_outer:
    lbu  t2, 0(t0)          # state[i]
    lhu  t3, 0(t5)          # w = fact[i]
    addi t1, t0, 1          # j = i + 1

lehmer_inner:
    lbu  a0, 0(t1)          # state[j]
    bgeu a0, t2, lehmer_skip
    add  s0, s0, t3         # p += w

lehmer_skip:
    addi t1, t1, 1          # j++
    bltu t1, t6, lehmer_inner

    addi t0, t0, 1          # i++
    addi t5, t5, 2          # next .half
    bltu t0, t4, lehmer_outer

    # ---------------------------------------------------------------
    # 2. IDA* search (see ida/search.c).  All fields of the current node
    #    live in registers; memory is touched only on push and pop.
    #
    #    s0  p        current node            t0  cp      child after `turn`
    #    s1  o        current node            t1  co      quarter turns of `face`
    #    s2  f        current frame pointer   t2  pp      perm row of `face`
    #    s3  g        depth of current node   t3  op      ori row of `face`
    #    s4  bound                            t4  face    0..2, 3 = all tried
    #    s5  &perm_pdb                        t5  turn    0..3
    #    s6  &ori_pdb                         t6  face of the move being tried
    #    s7  &perm_row                        a0..a3      scratch (h, loads,
    #    s8  &ori_row                                     the move's turn)
    #                                         a4  limit = bound - g - 1
    #    s9  mface    current node (0xFF = root, no face equals it)
    #    s10 3        constant: turn == 3, face == 3
    #    s11 &stack   root frame, to know when the root is exhausted
    #
    #    push writes: parent's cp, co, pp, op, face, turn into its frame,
    #                 child's p, o, mface, mturn into the child frame
    #    pop reads:   p, o, cp, co, pp, op, face, turn, mface
    #    h == 0 exactly when the state is solved, so computing h also
    #    finds the solution.
    # ---------------------------------------------------------------

    # Constants and table addresses: s5..s8, s10, s11.
    la   s5, perm_pdb
    la   s6, ori_pdb
    la   s7, perm_row
    la   s8, ori_row
    la   s11, stack
    li   s10, 3

    # Root frame: store p0, o0 so every iteration can start from them.
    sh   s0, 0(s11)
    sh   s1, 2(s11)

    # h(root) = max(perm_pdb[p0], ori_pdb[o0])
    add  a2, s5, s0
    lbu  a0, 0(a2)
    add  a3, s6, s1
    lbu  a1, 0(a3)
    bgeu a0, a1, root_h_done
    mv   a0, a1

root_h_done:
    # If h(root) == 0, the cube is already solved: g = 0, go to found.
    li   s3, 0              # g = 0 before found can read it
    beqz a0, found
    mv   s4, a0             # bound = h(root)

iter_start:
    # f = &stack, g = 0
    mv   s2, s11            # f = &stack
    li   s3, 0              # g = 0
    addi a4, s4, -1         # limit = bound - 1 (g = 0), recomputed every round
    # p, o = root's p, o (from the root frame)
    lhu  s0, 0(s11)         # p
    lhu  s1, 2(s11)         # o
    # face = 0, turn = 0, mface = 0xFF
    li   t4, 0              # face = 0
    li   t5, 0              # turn = 0
    li   s9, 255            # mface = NONE (0xFF)
    sb   s9, 18(s11)        # root frame's mface too, read back by pop
    j    face_start        # pop is below: do not fall into it

pop:
    # If f == &stack: the root is exhausted: go to next_bound.
    # f -= 20, g -= 1
    # Load p, o, cp, co, pp, op, face, turn, mface from frame f.
    # Continue the parent like after a pruned child: go to prune.
    beq  s2, s11, next_bound

    addi s2, s2, -20        # f -= 20
    addi s3, s3, -1         # g -= 1
    addi a4, a4, 1          # limit += 1

    lhu  s0, 0(s2)          # p
    lhu  s1, 2(s2)          # o
    lhu  t0, 4(s2)          # cp
    lhu  t1, 6(s2)          # co
    lw   t2, 8(s2)          # pp
    lw   t3, 12(s2)         # op
    lbu  t4, 16(s2)         # face
    lbu  t5, 17(s2)         # turn
    lbu  s9, 18(s2)         # mface

    # (falls through into prune, laid out right below)

prune:
    # The child is cut.  If turn == 0, the face just finished: face_start.
    # Otherwise try the next quarter turn of the same face: child.
    #     Laid out right above face_start: turn != 0 jumps to child,
    #     turn == 0 falls through into face_start.
    bnez t5, child

face_start:
    # Same-face pruning: if face == mface, face += 1.
    # If face == 3, every face of this node is tried: go to pop.
    # cp = p, co = o
    # pp = perm_row[face], op = ori_row[face]      (face * 4: a shift)
    #     No second face == mface test: after face += 1, face is mface + 1.
    bne  t4, s9, face_ok
    addi t4, t4, 1

face_ok:
    beq  t4, s10, pop

    mv   t0, s0             # cp = p
    mv   t1, s1             # co = o

    slli a0, t4, 2          # face * 4, used for both row tables

    add  a1, s7, a0         # &perm_row[face]
    lw   t2, 0(a1)          # pp

    add  a1, s8, a0         # &ori_row[face]
    lw   t3, 0(a1)          # op

child:
    # One more quarter turn: cp = pp[cp], co = op[co]  (.half: index * 2)
    # t6 = face, and keep the move's turn (1..3) in a scratch register,
    #      before face and turn may change below
    # turn += 1
    # If turn == 3: turn = 0, face += 1   (R' done; next time, a new face)

    slli a0, t0, 1          # cp = pp[cp]
    add  a0, t2, a0
    lhu  t0, 0(a0)

    slli a0, t1, 1          # co = op[co]
    add  a0, t3, a0
    lhu  t1, 0(a0)

    mv   t6, t4             # face of this move, for the child's mface
    addi t5, t5, 1          # turn += 1
    mv   a3, t5             # this move's turn (1..3), for the child's mturn

    bne  t5, s10, child_turn_ok
    li   t5, 0              # R' done: turn = 0
    addi t4, t4, 1          #          face += 1

child_turn_ok:
    # h = max(perm_pdb[cp], ori_pdb[co])   (a0 keeps h for push)
    add  a0, s5, t0
    lbu  a0, 0(a0)
    add  a1, s6, t1
    lbu  a1, 0(a1)
    bgeu a0, a1, h_done
    mv   a0, a1

h_done:
    # If g + 1 + h > bound, that is h > limit: go to prune.
    bltu a4, a0, prune

push:
    # Store the parent's cp, co, pp, op, face, turn into frame f.
    # f += 20, g += 1
    # Store the child's p = cp, o = co, mface = t6, mturn = the move's turn
    # into the new frame f.
    # Registers become the child: p = cp, o = co, mface = t6,
    #                             face = 0, turn = 0
    # If h == 0: go to found.
    # Go to face_start.
    #     The child is written at 20(s2).. before f moves, so one addi
    #     at the end is enough.  found comes after the stores, so the
    #     last move is already in the stack.
    sh   t0, 4(s2)          # parent's cp
    sh   t1, 6(s2)          # parent's co
    sw   t2, 8(s2)          # parent's pp
    sw   t3, 12(s2)         # parent's op
    sb   t4, 16(s2)         # parent's face
    sb   t5, 17(s2)         # parent's turn

    sh   t0, 20(s2)         # child p = cp
    sh   t1, 22(s2)         # child o = co
    sb   t6, 38(s2)         # child mface
    sb   a3, 39(s2)         # child mturn

    addi s2, s2, 20         # f += 20
    addi s3, s3, 1          # g += 1
    addi a4, a4, -1         # limit -= 1

    mv   s0, t0             # p = cp
    mv   s1, t1             # o = co
    mv   s9, t6             # mface
    li   t4, 0              # face = 0
    li   t5, 0              # turn = 0

    beqz a0, found          # h == 0: solved
    j    face_start

next_bound:
    # bound += 1, go to iter_start.
    addi s4, s4, 1          # bound += 1
    j    iter_start

found:
    # g = solution length; the moves are frames 1..g, mface and mturn.

    # ---------------------------------------------------------------
    # 3. T5: replay the path from (p0, o0) with the quarter-turn tables;
    #    it must reach (0, 0).  Otherwise exit 1.
    # ---------------------------------------------------------------
verify:
    lhu  t0, 0(s11)         # p = p0
    lhu  t1, 2(s11)         # o = o0
    addi t2, s11, 20        # ptr = &stack[1]
    mv   t3, s3             # remaining steps = g

verify_step:
    beqz t3, verify_done
    lbu  t4, 18(t2)         # mface
    lbu  t5, 19(t2)         # mturn

    slli a0, t4, 2          # pp = perm_row[mface]
    add  a1, s7, a0
    lw   a1, 0(a1)
    add  a2, s8, a0         # op = ori_row[mface]
    lw   a2, 0(a2)

verify_turn:
    beqz t5, verify_next
    slli a0, t0, 1          # p = pp[p]
    add  a0, a1, a0
    lhu  t0, 0(a0)
    slli a0, t1, 1          # o = op[o]
    add  a0, a2, a0
    lhu  t1, 0(a0)
    addi t5, t5, -1
    j    verify_turn

verify_next:
    addi t2, t2, 20         # next frame
    addi t3, t3, -1         # one move consumed
    j    verify_step

verify_done:
    or   a0, t0, t1         # (p | o) == 0 exactly when both are 0
    bnez a0, fail

    # ---------------------------------------------------------------
    # 4. Print the moves: face letter from `names`, then nothing for one
    #    quarter turn, '2' for two, an apostrophe for three; a space
    #    between moves.
    # ---------------------------------------------------------------
print_path:
    la   t0, names          # names = "RBD"
    addi t1, s11, 20        # ptr = &stack[1]
    mv   t2, s3             # remaining moves = g
    li   t3, 1              # first move flag: no space before it

    # RENDER_BEGIN
    # p8/o8 from the input string (position 0 is the fixed corner),
    # then draw the scrambled cube.
    la   a1, p8
    la   a2, o8
    la   a3, state

    sb   x0, 0(a1)          # p8[0] = 0
    sb   x0, 0(a2)          # o8[0] = 0

    addi a1, a1, 1
    addi a2, a2, 1

    li   a4, 7

render_init_loop:
    lbu  a5, 0(a3)
    addi a5, a5, -48        # p8[i] = state[i - 1] - '0'
    sb   a5, 0(a1)

    lbu  a5, 7(a3)
    addi a5, a5, -49        # o8[i] = state[i + 6] - '1'
    sb   a5, 0(a2)

    addi a1, a1, 1
    addi a2, a2, 1
    addi a3, a3, 1

    addi a4, a4, -1
    bnez a4, render_init_loop

    jal  ra, render
    # RENDER_END

print_loop:
    beqz t2, print_done
    beqz t3, print_space

print_move:
    lbu  t4, 18(t1)         # mface
    lbu  t5, 19(t1)         # mturn

    add  a0, t0, t4         # face letter
    lbu  a0, 0(a0)
    li   a7, 11
    ecall

    li   a0, 2
    beq  t5, a0, print_2
    li   a0, 3
    beq  t5, a0, print_prime

print_after_suffix:
    # RENDER_BEGIN
    # Apply the move just printed to p8/o8 and redraw.  turn and render
    # leave t0..t5 alone, so t4 = mface and t5 = mturn are still valid,
    # and t5 can count the quarter turns down (it is reloaded next move).
    mv   a6, t4             # face
render_turn_loop:
    beqz t5, render_redraw
    jal  ra, turn
    addi t5, t5, -1
    j    render_turn_loop
render_redraw:
    jal  ra, render
    # RENDER_END
    li   t3, 0              # later moves get a space first
    addi t1, t1, 20
    addi t2, t2, -1
    j    print_loop

print_space:
    li   a0, 32             # ' '
    li   a7, 11
    ecall
    j    print_move

print_2:
    li   a0, 50             # '2'
    li   a7, 11
    ecall
    j    print_after_suffix

print_prime:
    li   a0, 39             # apostrophe
    li   a7, 11
    ecall
    j    print_after_suffix

print_done:
    li   a0, 10             # newline
    li   a7, 11
    ecall

    li   a0, 0              # exit 0: solved and verified
    li   a7, 93
    ecall

fail:
    li   a0, 1
    li   a7, 93
    ecall

invalid:
    li a0, 2
    li a7, 93
    ecall

# RENDER_BEGIN
# ---------------------------------------------------------------
# LED renderer (GUI build only).  The CLI build deletes everything from
# the begin marker to the end marker with sed, since LED_MATRIX_0_BASE
# exists only when an LED matrix is instantiated in the GUI.  (This comment
# must not spell the markers out, or sed would stop here.)
# Data: ida/render.s.  Called from print_path, so t0..t3 (print_path's
# live registers), s3 and s11 are left untouched.
# ---------------------------------------------------------------

# turn: one quarter turn of face a6 (0..2) on p8/o8, through p8b/o8b.
# Every new entry reads the old arrays, so the result goes to p8b/o8b first
# and is copied back afterwards (8 bytes each = 2 words, all 4-byte aligned).
turn:
    slli a1, a6, 3          # face * 8: one row of source8 / twist8

    la   s1, source8
    add  s1, s1, a1         # &source8[f][0]

    la   s2, twist8
    add  s2, s2, a1         # &twist8[f][0]

    la   s4, p8
    la   s5, o8
    la   s6, p8b
    la   s7, o8b

    li   s8, 8              # counter
    li   s9, 3              # constant 3

turn_loop:
    lbu  a2, 0(s1)          # src

    add  a3, s4, a2         # &p8[src]
    lbu  a3, 0(a3)
    sb   a3, 0(s6)          # p8b[i]

    add  a4, s5, a2         # &o8[src]
    lbu  a4, 0(a4)

    lbu  a5, 0(s2)          # twist
    add  a4, a4, a5         # t = o8[src] + twist  (at most 4)

    bltu a4, s9, turn_t_ok
    addi a4, a4, -3

turn_t_ok:
    sb   a4, 0(s7)          # o8b[i]

    addi s1, s1, 1          # source++
    addi s2, s2, 1          # twist++
    addi s6, s6, 1          # p8b++
    addi s7, s7, 1          # o8b++

    addi s8, s8, -1
    bnez s8, turn_loop

    la   s4, p8             # copy p8b -> p8
    la   s6, p8b
    lw   a1, 0(s6)
    lw   a2, 4(s6)
    sw   a1, 0(s4)
    sw   a2, 4(s4)

    la   s5, o8             # copy o8b -> o8
    la   s7, o8b
    lw   a1, 0(s7)
    lw   a2, 4(s7)
    sw   a1, 0(s5)
    sw   a2, 4(s5)

    ret

# render: draw the 24 facelets of p8/o8.  Position pos's sticker k shows
# sticker (k + o8[pos]) mod 3 of cubie p8[pos].
render:
    li   s0, LED_MATRIX_0_BASE

    la   s1, facelet_offset
    la   s2, facelet_pos
    la   s4, facelet_k
    la   s5, p8
    la   s6, o8
    la   s7, cubie_rgb

    li   s8, 24             # facelets left
    li   s9, 3              # mod-3 constant, outside the loop

render_loop:
    lbu  a1, 0(s2)          # pos
    lbu  a2, 0(s4)          # k

    add  a3, s5, a1
    lbu  a3, 0(a3)          # c = p8[pos]

    add  a4, s6, a1
    lbu  a4, 0(a4)          # o = o8[pos]

    add  a2, a2, a4         # j = k + o  (at most 4)
    bltu a2, s9, render_j_ok
    addi a2, a2, -3

render_j_ok:
    slli a3, a3, 4          # c * 16
    slli a2, a2, 2          # j * 4
    add  a3, a3, a2
    add  a3, s7, a3
    lw   a5, 0(a3)          # color = cubie_rgb[c][j]

    lw   a3, 0(s1)          # facelet offset
    add  a3, s0, a3         # addr of the top-left pixel

    sw   a5,   0(a3)        # row 0
    sw   a5,   4(a3)
    sw   a5,   8(a3)
    sw   a5,  12(a3)

    sw   a5, 140(a3)        # row 1 (35 * 4 bytes below)
    sw   a5, 144(a3)
    sw   a5, 148(a3)
    sw   a5, 152(a3)

    sw   a5, 280(a3)        # row 2
    sw   a5, 284(a3)
    sw   a5, 288(a3)
    sw   a5, 292(a3)

    addi s1, s1, 4          # next offset (.word)
    addi s2, s2, 1          # next pos (.byte)
    addi s4, s4, 1          # next k (.byte)

    addi s8, s8, -1
    bnez s8, render_loop

    ret
# RENDER_END
